SELECT u.UrunID, u.UrunKodu AS Kod, u.UrunAdi AS [Ürün Adı], u.Birim, Nz(u.AcilisStok,0) AS Açılış, Format(u.AlisFiyati,"#,##0.00") AS [Alış Fiyatı], Format(u.SatisFiyati,"#,##0.00") AS [Satış Fiyatı], u.MinimumStok AS [Min Stok], Nz(u.AcilisStok,0)+Nz(b.Toplam,0) AS [Mevcut Stok], IIf(Nz(u.Aktif,True),"Evet","Hayır") AS Aktif
FROM tbl_Urun AS u LEFT JOIN (SELECT UrunID, Sum(Nz(Giris,0)-Nz(Cikis,0)) AS Toplam FROM tbl_StokHareket WHERE IptalMi=False GROUP BY UrunID) AS b ON u.UrunID=b.UrunID
ORDER BY u.UrunAdi;